.container {
  position: relative;
}

.icon-play {
  cursor: pointer;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 64px;
}

.video-player-title {
  padding: 8px;
  position: absolute;
  z-index: 1;
  background: rgba(0, 0, 0, 0.3);
  width: 100%;
  font-size: 14px;
  font-weight: 500;
  color: #fff;
  text-transform: capitalize;
  top: 0;
  left: 0;
}
