.setup-passkey-modal-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  text-align: center;

  .setup-passkey-modal-title {
    font-size: 22px;
    font-weight: 600;
    margin: 0;
  }

  .setup-passkey-modal-description {
    font-size: 14px;
    font-weight: 400;
    margin: 0;
  }

  .setup-passkey-modal-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;

    svg {
      width: 16px;
      height: 16px;
    }
  }
}
