.login-passkey-form-container {
  display: flex;
  width: 100%;
  justify-content: center;
}

.login-passkey-form {
  width: 100%;

  &-title {
    text-align: center;
    font-size: 1.5rem;
    font-weight: bold;
  }

  &-button-container {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
  }
}

.verify-passkey {
  width: 100%;

  &-title {
    text-align: center;
    font-size: 1.5rem;
    font-weight: bold;
  }

  &-subtitle {
    text-align: center;
    font-size: 0.875rem;
    color: #6b7280;
  }

  &-icon-container {
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  &-button-container {
    margin-top: 1.25rem;
    display: flex;
    justify-content: center;
    gap: 0.5rem;
  }
}
