.og2-cameras-component {
  display: grid;
  grid-template-columns: 350px 1fr;
  gap: 16px;
}

.og2-cameras-camera-table-component {
  display: flex;
  flex-direction: column;
  gap: 8px;

  .ant-table-body {
    overflow-y: auto;
    height: calc(100vh - 328px);
  }

  .ant-select {
    .ant-select-selector {
      background-color: white !important;
    }
  }
}

.og2-cameras-right {
  .ant-table-body {
    overflow-y: auto;
    height: calc(100vh - 304px);
  }
}