@import '../../../assets/colors/dark.scss';

.login-component {
  background-image: url('../../../assets/images/bgg.jpg');

  [data-theme='light'] & {
    background-image: url('../../../assets/images/Backgound-Light.png');
  }

  display: flex;
  height: 100%;
  width: 100%;
  position: relative;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;

  .login-container {
    display: flex;
    transform: translate(-50%, -50%);
    top: 50%;
    left: 50%;
    position: relative;
    height: 80%;
  }

  .login-form {
    width: 600px;
    height: 100%;
    position: relative;
  }

  .hoasen-login-form {
    background: white !important;
  }

  .hoasen-namespace {
    color: black !important;
  }

  .left-login-component {
    position: absolute;
    width: 40%;
    max-width: 500px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: var(--color-auto-bg2);
    border: 1px solid var(--color-brand);

    box-sizing: border-box;
    border-radius: 10px;
    min-width: 500px;

    .select-type-login {
      .main-login-component {
        width: 100%;
        padding: 108px 0 16px 0;
        // padding: 130px 0 16px 0;
        display: flex;
      }
    }

    .logo-login-component {
      position: absolute;
      top: 0;
      left: 50%;
      transform: translate(-50%, -50%);
      z-index: 1;

      .logo {
        background: var(--color-brand);
        border: 5px solid var(--color-brand);

        box-sizing: border-box;
        border-radius: 50%;
        width: 168px;
        height: 168px;
        position: relative;

        img {
          position: absolute;
          width: 120px;
          height: 120px;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
        }
      }

      .dash-logo {
        background: white !important;
      }

      .hoasen-logo {
        background: #b11116 !important;
      }
    }

    .download-component {
      width: 100%;
      position: absolute;
      left: 50%;
      transform: translate(-50%, 0);
      text-align: center;

      .title {
        font-weight: bold;
        font-size: 15px;
        line-height: 18px;
        text-align: center;
        text-transform: uppercase;
        color: #028fd5;
        margin: 12px;
      }

      .download-btn {
        button {
          margin: 0 4px;
          width: 128px;
          height: 40px;
        }
      }
    }

    .tab-login-component-0 {
      position: absolute;
      top: 36%;
      left: 10%;
      cursor: pointer;
    }

    .tab-login-component-1 {
      position: absolute;
      top: 36%;
      right: 10%;
      cursor: pointer;
    }

    .tab-login-component-0:hover {
      color: #028fd5 !important;
      transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);
    }

    .tab-login-component-1:hover {
      color: #028fd5 !important;
      transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);
    }
  }

  .right-login-component {
    width: 50%;
  }
}

.hoasen-login-component {
  background-image: url('../../../assets/images/background_login_hoasen.jpg') !important;
}

.hoasen-login-banner {
  background-image: url('../../../assets/images/banner_login_hoasen.jpg');
  width: 600px;
  height: 100%;
  background-size: cover;
  background-position: 50%;
  background-repeat: no-repeat;
}

.hoasen-submit {
  &[disabled] {
    color: #434343 !important;
  }
}

.hoasen-input input {
  color: #434343 !important;
}

.hoasen-input input::placeholder {
  color: black !important;
  opacity: 0.6;
}

.first-step-login-component {
  width: 100%;

  .select-type {
    width: 100%;
    display: grid;
    grid-template-columns: 1fr 1fr;

    // grid-template-columns: 1fr 1fr;
    button {
      height: 48px;
    }

    .passkey-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }

    .ant-btn {
      border-radius: 0;
    }
  }

  .button-continue {
    margin-top: 16px;
    text-align: center;

    button {
      width: 136px;
    }
  }
}

._2sd-step-login-component {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 400px 1fr;

  .ant-form-item {
    margin: 0;
  }

  .ant-form-large .ant-form-item-control-input input {
    min-height: 32px;
  }

  .ant-input-prefix {
    margin: 4px 8px 4px 0;
  }

  .confirm-btn {
    padding-top: 16px;
    width: 100%;
    display: flex;
    justify-content: center;

    button {
      width: 136px;
      margin: 0 8px;
    }

    .ant-form-item {
      margin: 0;
    }
  }

  .feedback {
    min-height: 12px;
    padding-top: 8px;
    color: $light;

    span {
      cursor: pointer;
    }

    &:hover {
      span {
        color: $lightest;
      }
    }
  }

  .hoasen-feedback {
    color: #434343 !important;
  }
}

._3th-step-login-component {
  width: 100%;

  .select-namespaces {
    display: grid;
    grid-template-columns: 1fr 400px 1fr;

    .ant-select:focus {
      outline: $online auto 1px;
    }

    .ant-select:not(.ant-select-disabled):hover .ant-select-selector {
      border-color: $online;
    }

    .ant-select-selector {
      height: 47px !important;

      .ant-select-selection-placeholder {
        align-self: center;
      }

      .ant-select-selection-item {
        align-self: center;
      }
    }
  }

  .confirm-btn {
    margin-top: 16px;
    width: 100%;
    display: flex;
    justify-content: center;

    button {
      height: 40px;
      width: 136px;
      margin: 0 8px;
    }

    .ant-form-item {
      margin: 0;
    }

    .button-size-select {
      height: 40px;
      padding: 6.4px 20px;
      font-size: 16px;
      border-radius: 40px;
    }
  }
}

@media (max-width: 575.98px) {
  .login-component {
    .left-login-component {
      min-width: 100%;
      top: 47% !important;

      .select-type-login {
        .main-login-component {
          .first-step-login-component {
            padding: 10px;

            .select-type {
              button {
                width: 100%;
              }
            }
          }

          ._2sd-step-login-component {
            display: block;
            padding: 10px;
          }

          ._3th-step-login-component {
            .select-namespaces {
              display: block;
              padding: 10px;
            }

            .confirm-btn {
              margin-top: 6px !important;
              margin-bottom: 10px !important;
            }
          }
        }
      }
    }
  }
}

.login-button {

  &.disabled {
    &:hover {
      background-color: transparent !important;
      color: #028fd5 !important;
      border-color: #028fd5 !important;
      box-shadow: none !important;

      >svg {
        stroke: #028fd5;
      }
    }
  }

  &:hover {
    >svg {
      stroke: white;
    }
  }

  svg {
    width: 20px;
    height: 20px;
  }
}

.input-timeout {
  &.ant-input-affix-wrapper,
  .ant-input-affix-wrapper-focused {
    box-shadow: 0 0 0 2px rgba(166, 29, 36, 0.2) !important;
    -webkit-box-shadow: 0 0 0 2px rgba(166, 29, 36, 0.2);
  }
}