.tree-camera {
  list-style-type: none;
  padding: 0;
  margin: 0;
  overflow-y: auto;
  height: calc(100vh - 200px);
  display: flex;
  flex-direction: column;
  gap: 4px;
  &__group {
    border: 1px solid #A4A7AE;
    border-radius: 4px;
    // &--active {
    //   border: 1px solid rgb(14 147 71 / 70%);
    // }
    .icon-live-stream {
      margin-right: 8px;
    }
  }

  ul {
    list-style-type: none;
    padding: 0;
    margin: 0;
  }
  .camera-pin__action {
    .pin-icon {
      width: 24px;
      height: 24px;
      border-radius: 50%;
    }
    .pin-icon--active {
      background-color: #028fd5;
    }
  }

  .camera-parent {
    cursor: pointer;
    display: flex;
    padding: 8px 0;
    justify-content: space-between;
    // &:hover {
    //   color: white;
    // }
    .down-arrow__icon {
      margin-right: 8px;
      filter: invert(37%) sepia(85%) saturate(5992%) hue-rotate(142deg)
        brightness(100%) contrast(89%);
      transition: transform 0.3s ease;
    }
    .smooth-transition {
      transition: transform 0.6s ease;
    }
    &__action {
      padding-right: 6px;
      height: 20px;
      & .ant-dropdown-trigger {
        height: inherit;
      }
    }
    // .down-arrow__icon.open {
    //   transform: rotate(90deg);
    // }
  }
  .camera-children__wrap {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin: 0 0 8px 0;
    overflow: hidden;
    .camera-children {
      cursor: pointer;
      // border: 1px solid #028fd5;
      border-radius: 4px;
      padding: 6px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      // overflow-x: scroll;
      &.camera-live--active {
        border: 1px solid rgba(14, 147, 71, 0.7);
      }
      // &:hover {
      //   background-color: #093f22;
      //   color: white;
      // }
    }
  }
  .selected-camera {
    background-color: #093f22;
    color: white;
  }
  .camera-name__wrap {
    display: flex;
    align-items: center;
    gap: 10px;
    overflow: hidden;
    .camera-name__title {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      -webkit-line-clamp: 1;
      -webkit-box-orient: vertical;
    }
  }
  .camera-name__wrap {
    display: flex;
  }
}
.tree-camera > .tree-camera__item.tree-camera__group {
  padding: 0 12px !important;
}

.tree-camera__item .camera-children__wrap:nth-child(n + 2) {
  padding: 0 12px;
}
.camera-children__wrap.camera-children__root {
  padding: 0 !important;
}

.scroll-x {
  overflow-x: scroll !important;
}

#camera-children__body {
  display: flex;
  // overflow: hidden;
}
