body {
  color: var(--color-dark-text);

  > iframe {
    z-index: 0 !important;
    display: none !important;
  }
}

html[data-theme="light"] body {
  color: var(--color-light-text);

  // .ant-input-search {
  //   input {
  //     &::placeholder {
  //       color: var(--color-light-text) !important;
  //     }
  //   }
  // }
}

[data-theme="light"] .ant-layout {
  background-color: var(--color-white);
}

html {
  --color-dark-bg1: #000;
  --color-dark-bg2: #1f1e1e;
  --color-text-button: #a1a5b7;
  --color-dark-stroke: #555555;
  --color-dark-text: #ffffffa6;
  --color-dark-online: #109242;
  --color-dark-offline: #555555;
  --color-dark-maintain: #307cc3;
  --color-light-bg1: #ffffff;
  --color-light-bg2: #f2f5fa;
  --color-light-stroke: #cbd5e2;
  --color-light-text: #404040;
  --color-light-online: #109242;
  --color-light-offline: #555555;
  --color-light-maintain: #307cc3;

  // for both themes
  --color-white: #ffffff;
  --color-black: #000000;
  --color-brand: #028fd5;
  --color-brand-light: #6ecfff;
  --color-brand-dark: #1a6083;
  --color-success: #12b76a;
  --color-success-light: #32d583;
  --color-success-dark: #039855;
  --color-warning: #fdb022;
  --color-warning-light: #fec84b;
  --color-warning-dark: #f79009;
  --color-error: #f04438;
  --color-error-light: #f97066;
  --color-error-dark: #b42318;
  --color-grey: #a4a7ae;
  --color-grey-light: #c8caca;
  --color-grey-dark: #717680;

  // auto color
  --color-auto-bg1: var(--color-dark-bg1);
  --color-auto-bg2: var(--color-dark-bg2);
  --color-auto-text: var(--color-dark-text);
  --color-auto-stroke: var(--color-dark-stroke);
  --color-auto-online: var(--color-dark-online);
  --color-auto-offline: var(--color-dark-offline);
  --color-auto-maintain: var(--color-dark-maintain);
  --color-auto-text-button: var(--color-dark-text-button);

  ::-webkit-scrollbar {
    background-color: var(--color-auto-bg2);
  }

  ::-webkit-scrollbar-thumb {
    background-color: var(--color-brand);
  }

  body {
    background-color: var(--color-auto-bg1);
  }

  &[data-theme="light"] {
    --color-auto-bg1: var(--color-light-bg1);
    --color-auto-bg2: var(--color-light-bg2);
    --color-auto-text: var(--color-light-text);
    --color-auto-stroke: var(--color-light-stroke);
    --color-auto-online: var(--color-light-online);
    --color-auto-offline: var(--color-light-offline);
    --color-auto-maintain: var(--color-light-maintain);
    --color-auto-text-button: var(--color-light-text-button);
    --color-auto-text: var(--color-light-text);
  }
}

// RADIO GROUP
.ant-radio-group {
  .ant-radio-button-wrapper {
    height: 36px;
    border: none;
    background-color: var(--color-auto-bg2);

    &::before {
      content: none;
    }

    span {
      color: var(--color-brand);
    }

    &-checked {
      background-color: var(--color-brand) !important;

      span {
        color: var(--color-white) !important;
      }
    }
  }

  .ant-radio-button-wrapper:first-child {
    border-top-left-radius: 5px;
    border-bottom-left-radius: 5px;
  }

  .ant-radio-button-wrapper:last-child {
    border-top-right-radius: 5px;
    border-bottom-right-radius: 5px;
  }

  .ant-radio-button {
    padding-left: 16px;
    padding-right: 16px;

    & + span {
      height: 100%;
      display: flex;
      align-items: center;
      gap: 4px;
    }
  }
}

// PICKER

.ant-picker {
  background-color: var(--color-auto-bg2);
  border-color: var(--color-auto-stroke);
  color: var(--color-auto-text);

  .ant-picker-input > input {
    color: var(--color-auto-text);

    &::placeholder {
      color: var(--color-auto-stroke);
    }

    [data-theme="light"] & {
      &::placeholder {
        color: var(--color-grey);
      }
    }
  }

  .ant-picker-suffix {
    color: var(--color-auto-text);
  }

  .ant-picker-clear {
    color: var(--color-auto-text);
    background-color: var(--color-auto-bg2);
  }
}

.ant-picker-separator {
  color: var(--color-grey);
}

.ant-picker.ant-picker-disabled {
  background-color: var(--color-auto-bg2);
  border-color: var(--color-auto-stroke);
  color: var(--color-auto-stroke);

  .ant-picker-input > input {
    color: var(--color-auto-stroke);
  }

  .ant-picker-suffix {
    color: var(--color-auto-stroke);
  }
}

.ant-picker-dropdown {
  color: var(--color-auto-text);
}

.ant-picker-panel-container {
  background-color: var(--color-auto-bg2);
}

.ant-picker-panel {
  background-color: var(--color-auto-bg2);
  border-color: var(--color-auto-stroke);

  .ant-picker-header {
    color: var(--color-auto-text);
    border-color: var(--color-auto-stroke);

    button {
      color: var(--color-grey);
    }
  }
}

.ant-picker-content th {
  color: var(--color-auto-text);
}

.ant-picker-cell {
  color: var(--color-grey) !important;

  &.ant-picker-cell-selected {
    color: #fff !important;
  }

  .ant-picker-cell-inner {
    color: inherit !important;
  }
}

.ant-picker-cell-in-view {
  color: var(--color-auto-text) !important;
}

.ant-picker-cell-disabled {
  color: var(--color-grey) !important;

  &::before {
    background-color: transparent;
  }

  // .ant-picker-cell-inner {
  //   color: var(--color-grey);
  // }
}

.ant-picker-cell-in-view.ant-picker-cell-in-range {
  &::before {
    background-color: var(--color-brand-light);
  }

  &.ant-picker-cell-range-hover::before {
    background-color: var(--color-brand-light);
    opacity: 0.5;
  }

  &.ant-picker-cell-range-hover-start::before {
    background-color: var(--color-brand-light);
    opacity: 0.5;
  }
}

.ant-picker-date-panel
  .ant-picker-cell-in-view.ant-picker-cell-in-range.ant-picker-cell-range-hover-start
  .ant-picker-cell-inner::after,
.ant-picker-date-panel
  .ant-picker-cell-in-view.ant-picker-cell-in-range.ant-picker-cell-range-hover-end
  .ant-picker-cell-inner::after {
  background-color: var(--color-brand-light);
}

.ant-picker-cell-in-view.ant-picker-cell-in-range.ant-picker-cell-range-hover::before,
.ant-picker-cell-in-view.ant-picker-cell-range-start.ant-picker-cell-range-hover::before,
.ant-picker-cell-in-view.ant-picker-cell-range-end.ant-picker-cell-range-hover::before,
.ant-picker-cell-in-view.ant-picker-cell-range-start:not(
    .ant-picker-cell-range-start-single
  ).ant-picker-cell-range-hover-start::before,
.ant-picker-cell-in-view.ant-picker-cell-range-end:not(
    .ant-picker-cell-range-end-single
  ).ant-picker-cell-range-hover-end::before,
.ant-picker-panel
  > :not(.ant-picker-date-panel)
  .ant-picker-cell-in-view.ant-picker-cell-in-range.ant-picker-cell-range-hover-start::before,
.ant-picker-panel
  > :not(.ant-picker-date-panel)
  .ant-picker-cell-in-view.ant-picker-cell-in-range.ant-picker-cell-range-hover-end::before {
  background-color: var(--color-brand-light);
  opacity: 0.5;
}

.ant-picker-cell-in-view.ant-picker-cell-range-start:not(.ant-picker-cell-range-start-single),
.ant-picker-cell-in-view.ant-picker-cell-range-end:not(.ant-picker-cell-range-end-single) {
  &::before {
    background-color: var(--color-brand-light);
  }
}

.ant-picker-time-panel-column > li.ant-picker-time-panel-cell .ant-picker-time-panel-cell-inner {
  color: var(--color-auto-text);
}

.ant-picker-time-panel-column > li.ant-picker-time-panel-cell .ant-picker-time-panel-cell-inner:hover {
  color: var(--color-brand);
}

.ant-picker-time-panel-column:not(:first-child) {
  border-color: var(--color-auto-stroke);
}

.ant-picker-time-panel-column > li.ant-picker-time-panel-cell-selected .ant-picker-time-panel-cell-inner {
  color: var(--color-dark-text);
}

.ant-picker-panel .ant-picker-footer {
  border-color: var(--color-auto-stroke);
}

.ant-picker-range-arrow::after {
  border-color: var(--color-auto-bg2) var(--color-auto-bg2) transparent transparent;
}

// SELECT
.ant-select {
  color: var(--color-auto-text);

  .ant-select-selector {
    background-color: var(--color-auto-bg2) !important;
    border-color: var(--color-auto-stroke) !important;
  }

  .ant-select-clear {
    color: var(--color-auto-text);
    background-color: var(--color-auto-bg2);
  }

  .ant-select-arrow {
    color: var(--color-auto-text);
  }
}

.ant-select-single.ant-select-open .ant-select-selection-item {
  opacity: 1;
  color: var(--color-grey);
}

.ant-select-multiple .ant-select-selection-item {
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);

  .ant-select-selection-item-remove {
    color: var(--color-auto-text);
  }
}

.ant-select-disabled.ant-select-single:not(.ant-select-customize-input) .ant-select-selector {
  color: var(--color-grey);
}

.ant-select-dropdown {
  background-color: var(--color-auto-bg2);
  color: var(--color-auto-text);

  .ant-select-item {
    color: var(--color-auto-text);

    &.ant-select-item-option-disabled {
      color: var(--color-auto-stroke);
    }
  }

  .ant-select-item-option-active:not(.ant-select-item-option-disabled) {
    background-color: var(--color-brand);
    color: var(--color-white);
  }

  .ant-select-item-option-selected:not(.ant-select-item-option-disabled) {
    background-color: var(--color-brand) !important;
    color: var(--color-white);
  }
}

// TREE
.group-node {
  background-color: var(--color-auto-bg1);
}

.group-node .group-node-header .group-node-header-name {
  color: var(--color-auto-text);
}

.group-node .group-node-header .group-node-header-actions .group-node-header-action {
  color: var(--color-grey);
}

.group-node.group-node-expanded .node {
  border-top-color: var(--color-auto-stroke);
}

.group-node.group-node-root {
  border-color: var(--color-auto-stroke);
}

.device-node .device-node-name {
  color: var(--color-auto-text);
}

.device-node-selected {
  border-top: 1px solid var(--color-brand) !important;
  border-bottom: 1px solid var(--color-brand) !important;
  font-weight: 500;
}

.device-node-selected .device-node-name {
  color: var(--color-brand);
}

.device-node:hover .device-node-name {
  color: var(--color-brand);
}

.device-node-root {
  border-color: var(--color-auto-stroke);
}

// PAGINATION

.ant-pagination-item-link,
.ant-pagination-item-link {
  color: var(--color-brand-light) !important;
  border-color: transparent !important;
}

.ant-pagination.mini .ant-pagination-prev .ant-pagination-item-link,
.ant-pagination.mini .ant-pagination-next .ant-pagination-item-link {
  color: var(--color-brand-light) !important;
}

.ant-pagination-prev .ant-pagination-item-link,
.ant-pagination-next .ant-pagination-item-link {
  display: flex;
  align-items: center;
}

.ant-pagination.mini {
  .ant-pagination-item {
    border-color: transparent !important;
  }
}

.ant-pagination-item {
  border-color: var(--color-auto-stroke) !important;

  a {
    color: var(--color-grey) !important;
  }
}

.ant-pagination-item.ant-pagination-item-active {
  background-color: var(--color-brand) !important;
  border-color: var(--color-brand) !important;

  a {
    color: var(--color-white) !important;
  }

  &:hover a {
    color: var(--color-white) !important;
  }
}

.ant-pagination-item:hover {
  a {
    color: var(--color-brand) !important;
  }
}

.ant-pagination-jump-prev .ant-pagination-item-container .ant-pagination-item-link-icon,
.ant-pagination-jump-next .ant-pagination-item-container .ant-pagination-item-link-icon {
  color: var(--color-brand-light);
}

.ant-pagination-jump-prev .ant-pagination-item-container .ant-pagination-item-ellipsis,
.ant-pagination-jump-next .ant-pagination-item-container .ant-pagination-item-ellipsis {
  color: var(--color-grey);
}

// HEADER
.ant-layout-header {
  background-color: var(--color-dark-bg2);
  color: var(--color-white);

  [data-theme="light"] & {
    background-color: var(--color-brand);
  }

  .ant-menu-horizontal.ant-menu-dark,
  .ant-menu-dark .ant-menu-sub,
  .ant-menu-horizontal.ant-menu-dark .ant-menu-sub {
    background-color: var(--color-dark-bg2);

    [data-theme="light"] & {
      background-color: var(--color-brand);
    }
  }

  .ant-menu-dark .ant-menu-item,
  .ant-menu-dark .ant-menu-item-group-title,
  .ant-menu-dark .ant-menu-item > a,
  .ant-menu-dark .ant-menu-item > span > a {
    color: var(--color-white);

    &.ant-menu-item-selected:not(.ant-menu-item-active) {
      a {
        color: var(--color-brand);
      }

      [data-theme="light"] & {
        a {
          color: var(--color-white);
        }
      }
    }
  }
}

.ant-menu.ant-menu-dark,
.ant-menu-dark .ant-menu-sub,
.ant-menu.ant-menu-dark .ant-menu-sub {
  background-color: var(--color-auto-bg2);
}

.ant-menu-dark .ant-menu-item-selected {
  color: var(--color-white) !important;
}

.ant-menu-dark .ant-menu-item-active {
  color: var(--color-brand) !important;
}

.ant-menu-dark .ant-menu-item,
.ant-menu-dark .ant-menu-item-group-title,
.ant-menu-dark .ant-menu-item > a,
.ant-menu-dark .ant-menu-item > span > a {
  color: var(--color-auto-text);
}

// POPOVER
// .ant-popover {
//   z-index: 100000000000000 !important;
// }

.ant-popover-inner {
  background-color: var(--color-auto-bg2);
  // box-shadow: none;
  // border: 1px solid var(--color-auto-stroke);
  // border: none;
}

.ant-popover-title {
  color: var(--color-auto-text);
}

.ant-popover-content {
  color: var(--color-auto-text);
}

.ant-popover-placement-bottom > .ant-popover-content > .ant-popover-arrow,
.ant-popover-placement-bottomLeft > .ant-popover-content > .ant-popover-arrow,
.ant-popover-placement-bottomRight > .ant-popover-content > .ant-popover-arrow {
  border-top-color: var(--color-auto-bg2);
  border-left-color: var(--color-auto-bg2);
}

.ant-popover-inner-content {
  color: var(--color-auto-text);
}

.ant-popover-message {
  color: var(--color-auto-text);
}

// DRAWER
.ant-drawer-content {
  background-color: var(--color-auto-bg2);
}

.ant-drawer-close {
  color: var(--color-auto-text);
}

// MODAL

.ant-modal {
  color: var(--color-auto-text);
}

.ant-modal-content {
  background-color: var(--color-auto-bg2);
  z-index: 100000 !important;
}

.ant-modal-header {
  background-color: var(--color-auto-bg2);
  border-bottom: 1px solid var(--color-auto-stroke);
}

.ant-modal-title {
  color: var(--color-auto-text);
}

.ant-modal-close {
  color: var(--color-auto-text);

  &:hover {
    color: var(--color-auto-text);
  }
}

.ant-modal-confirm-body .ant-modal-confirm-title {
  color: var(--color-auto-text);
}

.ant-modal-confirm-body .ant-modal-confirm-content {
  color: var(--color-grey);
}

// FORM
.ant-form {
  color: var(--color-auto-text);
}

.ant-form-item-label > label {
  color: var(--color-auto-text);
}

// INPUT

.ant-input {
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);

  &::placeholder {
    color: var(--color-auto-stroke);
  }

  [data-theme="light"] & {
    &::placeholder {
      color: var(--color-grey);
    }
  }

  &[disabled] {
    color: var(--color-grey);
    background-color: var(--color-auto-bg2);

    &:hover {
      border-color: var(--color-auto-stroke);
    }
  }
}

.ant-input-number {
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);
}

.ant-input-number-handler-wrap {
  background-color: var(--color-auto-bg2);
  border-color: var(--color-auto-stroke);
}

.ant-input-number-handler {
  color: var(--color-grey);
}

.ant-input-number-handler-up-inner,
.ant-input-number-handler-down-inner {
  color: var(--color-grey);
}

.ant-input-number-handler-down {
  border-color: var(--color-auto-stroke);
}

.ant-input-affix-wrapper {
  border-color: var(--color-auto-stroke);
  color: var(--color-grey);
  background-color: var(--color-auto-bg2);
}

.ant-input-search-icon::before {
  border-color: var(--color-auto-stroke);
}

.ant-input-search-icon {
  color: var(--color-grey);
}

.ant-input-clear-icon,
.ant-input-search-icon {
  color: var(--color-auto-text);

  .ant-input-affix-wrapper:hover & {
    color: var(--color-auto-text);
  }
}

// CHECKBOX
.ant-checkbox {
  color: var(--color-auto-text);
}

.ant-checkbox-inner {
  border-color: var(--color-brand);
}

.ant-checkbox-wrapper {
  color: var(--color-auto-text);
}

.ant-checkbox-disabled + span {
  color: var(--color-auto-stroke);
}

.ant-checkbox-indeterminate .ant-checkbox-inner {
  border-color: var(--color-brand);
}

.ant-checkbox-disabled .ant-checkbox-inner {
  border-color: var(--color-auto-stroke) !important;
}

.ant-checkbox-disabled.ant-checkbox-checked .ant-checkbox-inner {
  border-color: var(--color-brand) !important;
}

// BUTTON
.ant-btn {
  &,
  &:focus,
  &:focus:hover,
  &[disabled] {
    color: var(--color-brand);
    border-color: var(--color-brand);
  }

  &:hover {
    color: var(--color-white);
    background-color: var(--color-brand);
  }
}

.ant-btn-primary {
  &,
  &:focus,
  &:focus:hover,
  &[disabled] {
    color: var(--color-white);
    border-color: var(--color-brand);
    background-color: var(--color-brand);
  }

  &:hover {
    background-color: transparent;
    color: var(--color-brand);
    border-color: var(--color-brand);
  }
}

.ant-btn[disabled],
.ant-btn[disabled]:hover,
.ant-btn[disabled]:focus,
.ant-btn[disabled]:active {
  opacity: 0.5;
}

.ant-btn-primary[disabled],
.ant-btn-primary[disabled]:hover,
.ant-btn-primary[disabled]:focus,
.ant-btn-primary[disabled]:active {
  color: var(--color-white);
  border-color: var(--color-brand);
  background-color: var(--color-brand);
}

.ant-btn-dashed[disabled],
.ant-btn-dashed[disabled]:hover,
.ant-btn-dashed[disabled]:focus,
.ant-btn-dashed[disabled]:active {
  color: var(--color-white);
  border-color: var(--color-brand);
  background-color: var(--color-brand);
}

// TABLE
.ant-table {
  background-color: var(--color-auto-bg1);
  color: var(--color-auto-text);
  border: 1px solid var(--color-auto-stroke);
}

.ant-table-thead > tr > th {
  background-color: var(--color-auto-bg2);
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);
  font-weight: 700;
}

.ant-modal .ant-table.ant-table-small thead > tr > th {
  background-color: var(--color-auto-bg1);
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);
}

.ant-table-thead th.ant-table-column-has-sorters:hover {
  background-color: var(--color-auto-bg2);
}

.ant-table-thead th.ant-table-column-sort {
  background-color: var(--color-auto-bg2);
}

.ant-table-small .ant-table-thead > tr > th {
  background-color: var(--color-auto-bg1);
}

.ant-table-tbody > tr > td {
  border-bottom: 1px solid var(--color-auto-stroke);
  background-color: var(--color-auto-bg1);
}

.ant-table-tbody > tr.ant-table-row:hover > td {
  background-color: var(--color-auto-bg2);
}

.ant-table-tbody > tr.ant-table-row-selected > td {
  background-color: var(--color-auto-bg2);
}

tr.ant-table-expanded-row > td,
tr.ant-table-expanded-row:hover > td {
  background-color: var(--color-auto-bg2);
}

.ant-table-empty .ant-table-tbody > tr.ant-table-placeholder {
  background-color: var(--color-auto-bg2);
  color: var(--color-auto-stroke);
}

.ant-table-tbody > tr.ant-table-placeholder:hover > td {
  background-color: var(--color-auto-bg1);
}

td.ant-table-column-sort {
  background-color: var(--color-auto-bg2);
}

.ant-modal .ant-table tbody > tr > td {
  border-color: var(--color-auto-stroke);
}

.ant-modal .ant-table thead > tr > th {
  border-color: var(--color-auto-stroke);
  background-color: var(--color-auto-bg2);
}

.ant-modal .ant-table tbody > tr.ant-table-row:hover > td {
  background-color: var(--color-auto-bg2);
}

.ant-table-cell-scrollbar {
  box-shadow: 0 1px 0 1px var(--color-auto-stroke);
}

.ant-table-body::-webkit-scrollbar-thumb {
  background-color: var(--color-auto-stroke) !important;
}

.ant-table-cell-scrollbar {
  box-shadow: none;
}

.ant-table-footer {
  background-color: var(--color-auto-bg2);
}

// PROGRESS
.ant-progress {
  color: var(--color-auto-text);
}

.ant-progress-line .ant-progress-inner {
  background-color: rgba(255, 255, 255, 0.1);

  [data-theme="light"] & {
    background-color: rgba(0, 0, 0, 0.1);
  }
}

.ant-progress-text {
  color: var(--color-dark-stroke);
}

.ant-progress-circle .ant-progress-text {
  color: var(--color-auto-text);
}

.ant-progress-circle-trail {
  stroke: var(--color-auto-stroke);
}

// DIVIDER
[data-theme="dark"] {
  .ant-divider-horizontal.ant-divider-with-text {
    color: var(--color-grey);
  }
}

[data-theme="light"] {
  .ant-divider-horizontal.ant-divider-with-text {
    color: var(--color-black);
  }
}

.ant-divider-horizontal.ant-divider-with-text::before,
.ant-divider-horizontal.ant-divider-with-text::after {
  border-color: var(--color-auto-stroke);
}

// TABS
.ant-tabs {
  color: var(--color-auto-text);
}

.ant-tabs-top > .ant-tabs-nav::before,
.ant-tabs-bottom > .ant-tabs-nav::before,
.ant-tabs-top > div > .ant-tabs-nav::before,
.ant-tabs-bottom > div > .ant-tabs-nav::before {
  border-color: var(--color-auto-stroke);
}

.ant-tabs-dropdown {
  color: var(--color-auto-text);
}

.ant-tabs-dropdown-menu {
  background-color: var(--color-auto-bg2);
}

.ant-tabs-dropdown-menu-item {
  color: var(--color-auto-text);

  &:hover {
    background-color: var(--color-brand);
    color: var(--color-white);
  }
}

.ant-tabs-card > .ant-tabs-nav .ant-tabs-tab,
.ant-tabs-card > div > .ant-tabs-nav .ant-tabs-tab {
  border-color: var(--color-auto-stroke);
}

.ant-tabs-card.ant-tabs-top > .ant-tabs-nav .ant-tabs-tab-active,
.ant-tabs-card.ant-tabs-top > div > .ant-tabs-nav .ant-tabs-tab-active {
  border-bottom-color: var(--color-brand);
}

.ant-tabs-card > .ant-tabs-nav .ant-tabs-tab-active,
.ant-tabs-card > div > .ant-tabs-nav .ant-tabs-tab-active {
  background-color: var(--color-auto-bg2);
}

// .ant-tabs-nav .ant-tabs-tab,
// .ant-tabs-nav .ant-tabs-tab-active,
// .ant-tabs-tab.ant-tabs-tab-active .ant-tabs-tab-btn .ant-pagination-item:focus a,
// .ant-pagination-item a {
//   color: var(--color-auto-text);
// }

// STEPS

.ant-steps-item-process > .ant-steps-item-container > .ant-steps-item-content > .ant-steps-item-title::after {
  background-color: var(--color-auto-stroke);
}

.ant-steps-item-wait > .ant-steps-item-container > .ant-steps-item-content > .ant-steps-item-title::after {
  background-color: var(--color-auto-stroke);
}

.ant-steps-item-process > .ant-steps-item-container > .ant-steps-item-content > .ant-steps-item-title {
  color: var(--color-auto-text);
}

.ant-steps-item-finish > .ant-steps-item-container > .ant-steps-item-content > .ant-steps-item-title {
  color: var(--color-auto-text);
}

.ant-steps-item-wait > .ant-steps-item-container > .ant-steps-item-content > .ant-steps-item-title {
  color: var(--color-auto-stroke);
}

.ant-steps-item-wait .ant-steps-item-icon {
  border-color: var(--color-auto-stroke);
}

.ant-steps-item-wait .ant-steps-item-icon > .ant-steps-icon {
  color: var(--color-auto-stroke);
}

.ant-steps-navigation .ant-steps-item::after {
  border-color: var(--color-auto-stroke);
}

// RESULT
.ant-result-title {
  color: var(--color-auto-text);
}

// TYPO
.ant-typography {
  color: var(--color-auto-text);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--color-auto-text);
}

// RADIO
.ant-radio-wrapper {
  color: var(--color-auto-text);
}

.ant-radio {
  color: var(--color-auto-text);
}

// CARD
.ant-card {
  background-color: var(--color-auto-bg2);
  color: var(--color-auto-text);
}

.ant-card-bordered {
  border-color: var(--color-auto-stroke);
}

.ant-card-head {
  color: var(--color-auto-text);
  border-color: var(--color-auto-stroke);
}

// EMPTY
.ant-empty {
  color: var(--color-grey);
}

.ant-empty-description {
  color: var(--color-grey);
}

.ant-empty-img-simple-g {
  stroke: var(--color-grey);
}

.ant-empty-img-simple-path {
  fill: var(--color-grey);
  stroke: var(--color-grey);
}

// DROPDOWN
.ant-dropdown {
  color: var(--color-auto-text);
}

.ant-dropdown-menu {
  background-color: var(--color-auto-bg2);
}

.ant-dropdown-menu-item,
.ant-dropdown-menu-submenu-title {
  color: var(--color-auto-text);
}

.ant-dropdown-menu-item-disabled,
.ant-dropdown-menu-submenu-disabled {
  color: var(--color-auto-stroke);
}

.ant-dropdown-menu-item-selected,
.ant-dropdown-menu-submenu-title-selected {
  background-color: var(--color-brand);
}

.ant-dropdown-menu-item:hover,
.ant-dropdown-menu-submenu-title:hover {
  background-color: var(--color-brand);
  color: var(--color-white);
}

// TOOLTIP
.ant-tooltip {
  color: var(--color-auto-text);
  width: fit-content;
  z-index: 99999999999999999;
}

.ant-tooltip-inner {
  background-color: var(--color-auto-bg2);
  color: var(--color-auto-text);
  border-radius: 6px;
  // border: 1px solid var(--color-auto-stroke);
}

.ant-tooltip-arrow-content {
  background-color: var(--color-auto-bg2);
}

// SPIN
.ant-spin-container::after {
  background-color: var(--color-auto-bg2);
}

// SWITCH
.ant-switch {
  [data-theme="light"] & {
    background-color: var(--color-auto-stroke);
  }
}

// LIST
.ant-list-bordered {
  border-color: var(--color-auto-stroke);
}

.ant-list-item {
  color: var(--color-auto-text);

  &:hover {
    color: var(--color-brand);
  }
}

.ant-list-split .ant-list-item {
  border-bottom: 1px solid var(--color-auto-stroke);
}

// BADGE
.ant-badge .ant-badge-count {
  color: #6cceff !important;
  box-shadow: 0 0 0 1px #6cceff;
  background-color: var(--color-white);
}

// TAG
.ant-tag,
.ant-tag a,
.ant-tag a:hover {
  color: var(--color-auto-text);

  &.ant-tag-has-color {
    border-color: transparent;
    color: var(--color-white);
  }
}

.ant-tag {
  border-color: var(--color-auto-stroke);
}

// CUSTOM TAB
.ant-tabs.ant-tabs-top.custom-tabs {
  .ant-tabs-nav {
    margin-bottom: 8px;

    &::before {
      display: none;
    }

    .ant-tabs-ink-bar {
      display: none;
    }

    .ant-tabs-tab {
      padding: 0;
      margin: 0;

      .ant-tabs-tab-btn {
        display: flex;
        gap: 8px;
        height: 36px;
        align-items: center;
        padding: 0 16px;
        background-color: var(--color-auto-bg2);
        color: var(--color-brand);
      }

      &.ant-tabs-tab-active {
        .ant-tabs-tab-btn {
          background-color: var(--color-brand);
          color: var(--color-white);
        }
      }

      &:first-child {
        .ant-tabs-tab-btn {
          border-top-left-radius: 4px;
          border-bottom-left-radius: 4px;
        }
      }

      &:not(:first-child) {
        .ant-tabs-tab-btn {
          border-top-right-radius: 4px;
          border-bottom-right-radius: 4px;
        }
      }
    }
  }
}

.ant-select {
  .ant-select-selector {
    background-color: white !important;
  }
}

.ant-tooltip-inner {
  width: fit-content !important;
}

.ant-popover {
  // z-index: 100000000000000 !important;
}

.ant-tag-green {
  background-color: var(--color-success);
  color: var(--color-white);
}
